def main() -> None:
    for gal, rows in DATA.items():
        with open(OUT_DIR / f"{gal}_rotmod.dat", "w", encoding="utf-8") as f:
            for r in rows:
                f.write(" ".join(f"{x:.6g}" for x in r) + "\n")
    print(f"✔ LOTE MEGA 01 inyectado ({len(DATA)} galaxias de alta densidad)")


if __name__ == "__main__":
    main()
